CREATE TABLE IF NOT EXISTS trade_cases(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,reference TEXT NOT NULL,payload JSONB NOT NULL,controls JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'intake' CHECK(status IN('intake','screened','classified','documents_ready','review_pending','approved','rejected','blocked','filed')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,approved_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS trade_case_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id BIGINT NOT NULL REFERENCES trade_cases(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_status TEXT,to_status TEXT,event_data JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION reject_trade_event_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'trade history is append-only';END$$;DROP TRIGGER IF EXISTS trade_case_events_immutable ON trade_case_events;CREATE TRIGGER trade_case_events_immutable BEFORE UPDATE OR DELETE ON trade_case_events FOR EACH ROW EXECUTE FUNCTION reject_trade_event_mutation();CREATE INDEX IF NOT EXISTS trade_cases_tenant_status_idx ON trade_cases(tenant_id,status,updated_at DESC);

